/**
 * Fail-closed hosted production mutation gate.
 * Blocks apply/deploy/worker start unless every required control is present
 * and staging/production project refs are distinct.
 *
 * Does not print secret values — only presence and classification codes.
 *
 * Usage:
 *   node scripts/production-mutation-guard.mjs
 *   node scripts/production-mutation-guard.mjs --expected-commit=<sha> --expected-manifest-sha=<sha>
 */
import process from "node:process";

const STAGING_REFS = Object.freeze(["ufmtvqtsklqsmqxefbbs", "kbdotviopwlcqviggtrc"]);

const REQUIRED = Object.freeze([
  "PICOM_ENVIRONMENT",
  "SUPABASE_PRODUCTION_PROJECT_REF",
  "SUPABASE_PRODUCTION_URL",
  "SUPABASE_PRODUCTION_DB_HOST",
  "SUPABASE_PRODUCTION_ORG_ID",
  "PRODUCTION_CHANGE_TICKET",
  "PRODUCTION_DEPLOY_APPROVED",
  "EXPECTED_RELEASE_COMMIT",
  "EXPECTED_MIGRATION_MANIFEST_SHA256",
]);

function parseArgs(argv) {
  const out = { expectedCommit: null, expectedManifestSha: null };
  for (const arg of argv) {
    if (arg.startsWith("--expected-commit=")) out.expectedCommit = arg.slice("--expected-commit=".length);
    if (arg.startsWith("--expected-manifest-sha=")) {
      out.expectedManifestSha = arg.slice("--expected-manifest-sha=".length);
    }
  }
  return out;
}

function present(name) {
  const v = process.env[name];
  return typeof v === "string" && v.trim().length > 0;
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  const errors = [];

  for (const key of REQUIRED) {
    if (!present(key)) errors.push(`MISSING_${key}`);
  }

  // Access token OR CI identity — either is acceptable; both missing is blocked.
  if (!present("SUPABASE_ACCESS_TOKEN") && !present("PICOM_CI_SUPABASE_IDENTITY")) {
    errors.push("MISSING_SUPABASE_ACCESS_TOKEN_OR_CI_IDENTITY");
  }

  const envName = String(process.env.PICOM_ENVIRONMENT || "").trim().toLowerCase();
  if (present("PICOM_ENVIRONMENT") && envName !== "production") {
    errors.push("PICOM_ENVIRONMENT_NOT_PRODUCTION");
  }

  const approved = String(process.env.PRODUCTION_DEPLOY_APPROVED || "").trim().toLowerCase();
  if (present("PRODUCTION_DEPLOY_APPROVED") && approved !== "true") {
    errors.push("PRODUCTION_DEPLOY_APPROVED_NOT_TRUE");
  }

  const prodRef = String(process.env.SUPABASE_PRODUCTION_PROJECT_REF || "").trim();
  if (prodRef && STAGING_REFS.includes(prodRef)) {
    errors.push("FATAL_PRODUCTION_AND_STAGING_PROJECT_REFERENCES_MATCH");
  }

  const stagingRef = String(process.env.SUPABASE_STAGING_PROJECT_REF || "ufmtvqtsklqsmqxefbbs").trim();
  if (prodRef && stagingRef && prodRef === stagingRef) {
    errors.push("FATAL_PRODUCTION_AND_STAGING_PROJECT_REFERENCES_MATCH");
  }

  const prodUrl = String(process.env.SUPABASE_PRODUCTION_URL || "");
  if (prodRef && prodUrl && !prodUrl.includes(prodRef)) {
    errors.push("PRODUCTION_URL_REF_MISMATCH");
  }
  if (STAGING_REFS.some((ref) => prodUrl.includes(ref))) {
    errors.push("PRODUCTION_URL_POINTS_AT_STAGING");
  }

  const dbHost = String(process.env.SUPABASE_PRODUCTION_DB_HOST || "");
  if (prodRef && dbHost && !dbHost.includes(prodRef)) {
    errors.push("PRODUCTION_DB_HOST_REF_MISMATCH");
  }
  if (STAGING_REFS.some((ref) => dbHost.includes(ref))) {
    errors.push("PRODUCTION_DB_HOST_POINTS_AT_STAGING");
  }

  const expectedCommit = String(process.env.EXPECTED_RELEASE_COMMIT || "").trim();
  if (args.expectedCommit && expectedCommit && args.expectedCommit !== expectedCommit) {
    errors.push("EXPECTED_RELEASE_COMMIT_MISMATCH");
  }

  const expectedManifest = String(process.env.EXPECTED_MIGRATION_MANIFEST_SHA256 || "").trim().toLowerCase();
  if (args.expectedManifestSha && expectedManifest && args.expectedManifestSha.toLowerCase() !== expectedManifest) {
    errors.push("EXPECTED_MIGRATION_MANIFEST_SHA256_MISMATCH");
  }

  if (errors.length) {
    console.error("HOSTED_PRODUCTION_MUTATION=BLOCKED");
    for (const code of [...new Set(errors)]) {
      console.error(`CODE=${code}`);
    }
    process.exit(1);
  }

  console.log("HOSTED_PRODUCTION_MUTATION=ALLOWED");
  console.log(`PRODUCTION_PROJECT_REF=${prodRef}`);
  console.log(`EXPECTED_RELEASE_COMMIT=${expectedCommit}`);
  console.log(`EXPECTED_MIGRATION_MANIFEST_SHA256=${expectedManifest}`);
  process.exit(0);
}

main();

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const guard = path.join(root, "scripts", "production-mutation-guard.mjs");

function run(extraEnv = {}) {
  return spawnSync(process.execPath, [guard], {
    cwd: root,
    env: { ...process.env, ...extraEnv },
    encoding: "utf8",
  });
}

const complete = {
  PICOM_ENVIRONMENT: "production",
  SUPABASE_PRODUCTION_PROJECT_REF: "cqnsetsmcduraryemhbi",
  SUPABASE_PRODUCTION_URL: "https://cqnsetsmcduraryemhbi.supabase.co",
  SUPABASE_PRODUCTION_DB_HOST: "db.cqnsetsmcduraryemhbi.supabase.co",
  SUPABASE_PRODUCTION_ORG_ID: "agmihvcqyshjgwjgknor",
  SUPABASE_ACCESS_TOKEN: "test-token-not-logged",
  PRODUCTION_CHANGE_TICKET: "CHG-TEST-001",
  PRODUCTION_DEPLOY_APPROVED: "true",
  EXPECTED_RELEASE_COMMIT: "abc123",
  EXPECTED_MIGRATION_MANIFEST_SHA256: "deadbeef",
  SUPABASE_STAGING_PROJECT_REF: "ufmtvqtsklqsmqxefbbs",
};

test("mutation guard BLOCKED when required vars missing", () => {
  const result = run({
    PICOM_ENVIRONMENT: "",
    SUPABASE_PRODUCTION_PROJECT_REF: "",
    SUPABASE_PRODUCTION_URL: "",
    SUPABASE_PRODUCTION_DB_HOST: "",
    SUPABASE_PRODUCTION_ORG_ID: "",
    SUPABASE_ACCESS_TOKEN: "",
    PICOM_CI_SUPABASE_IDENTITY: "",
    PRODUCTION_CHANGE_TICKET: "",
    PRODUCTION_DEPLOY_APPROVED: "",
    EXPECTED_RELEASE_COMMIT: "",
    EXPECTED_MIGRATION_MANIFEST_SHA256: "",
  });
  assert.equal(result.status, 1);
  assert.match(result.stderr || "", /HOSTED_PRODUCTION_MUTATION=BLOCKED/);
  assert.match(result.stderr || "", /MISSING_PICOM_ENVIRONMENT/);
});

test("mutation guard FATAL when production ref equals staging", () => {
  const result = run({
    ...complete,
    SUPABASE_PRODUCTION_PROJECT_REF: "ufmtvqtsklqsmqxefbbs",
    SUPABASE_PRODUCTION_URL: "https://ufmtvqtsklqsmqxefbbs.supabase.co",
    SUPABASE_PRODUCTION_DB_HOST: "db.ufmtvqtsklqsmqxefbbs.supabase.co",
  });
  assert.equal(result.status, 1);
  assert.match(result.stderr || "", /FATAL_PRODUCTION_AND_STAGING_PROJECT_REFERENCES_MATCH/);
});

test("mutation guard ALLOWED when complete and distinct", () => {
  const result = run(complete);
  assert.equal(result.status, 0, result.stderr);
  assert.match(result.stdout || "", /HOSTED_PRODUCTION_MUTATION=ALLOWED/);
});

/**
 * Static migration-chain validation for Task 01–06 + publisher compatibility predecessors.
 * Does not claim Docker clean-reset PASS. Emits PASS_STATIC or FAIL.
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const migDir = path.join(root, "supabase", "migrations");

const CANONICAL_TASK_SHA = Object.freeze({
  "20260803173000_verification_business_platform_foundation.sql":
    "6fc0010d9a82e4b7fe0b0fdec95f686bedd6355b0456574de32cb04474dfd64c",
  "20260803210000_picom_verified_subscription_and_entitlements.sql":
    "a0a4ee0512f9be2fa33a22dd6299b25800f2a42f0cb67e7f5d1899a8a94d921d",
  "20260803220000_business_application_verification_and_team_management.sql":
    "be37310c444737a78f2bfc8950a6eb3c270b5783ebedde19d2f3357e4611b960",
  "20260803230000_business_catalog_brand_content_and_promotion_bridge.sql":
    "43908b6fca260fdb8fa3748d140873ac2e23661a9b78c813c12d0624ccc7e4d0",
  "20260803240000_advertiser_campaign_delivery_and_revenue_attribution.sql":
    "91b3d1990d6b3d1d46f2a89e3bf5a94da8e67b316419baa40bf17c86bfd846c9",
  "20260803250000_partner_payout_tax_reconciliation_and_ad_transparency.sql":
    "832e3c9be1d5963270972a9072e9eba0ea4b22768fed158ed81c326f36d788e3",
});

const COMPAT = Object.freeze([
  "20260803135000_platform_account_restrictions_canonical.sql",
  "20260803135100_notification_preferences_canonical.sql",
  "20260803135200_live_broadcaster_notification_prefs_canonical.sql",
  "20260803135300_profiles_deactivated_at_canonical.sql",
]);

function lfSha256(filePath) {
  const n = fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n").replace(/^\uFEFF/, "");
  return crypto.createHash("sha256").update(n, "utf8").digest("hex");
}

function main() {
  const errors = [];
  const files = fs
    .readdirSync(migDir)
    .filter((f) => f.startsWith("20260803") && f.endsWith(".sql"))
    .sort();

  for (const [name, expected] of Object.entries(CANONICAL_TASK_SHA)) {
    const full = path.join(migDir, name);
    if (!fs.existsSync(full)) {
      errors.push(`MISSING_${name}`);
      continue;
    }
    const actual = lfSha256(full);
    if (actual !== expected) errors.push(`SHA_MISMATCH_${name}`);
    else console.log(`SHA_OK ${name} ${actual}`);
  }

  for (const name of COMPAT) {
    const full = path.join(migDir, name);
    if (!fs.existsSync(full)) {
      errors.push(`MISSING_COMPAT_${name}`);
      continue;
    }
    const body = fs.readFileSync(full, "utf8");
    if (name.includes("platform_account_restrictions") && !body.includes("platform_account_restrictions")) {
      errors.push("COMPAT_RESTRICTIONS_MISSING_TABLE_DDL");
    }
    if (name.includes("profiles_deactivated") && !body.includes("deactivated_at")) {
      errors.push("COMPAT_DEACTIVATED_AT_MISSING_COLUMN_DDL");
    }
    console.log(`COMPAT_OK ${name} ${lfSha256(full)}`);
  }

  const idx140 = files.indexOf("20260803140000_publisher_creator_program_core.sql");
  const idx135 = files.indexOf("20260803135000_platform_account_restrictions_canonical.sql");
  const idx353 = files.indexOf("20260803135300_profiles_deactivated_at_canonical.sql");
  if (!(idx135 >= 0 && idx353 >= 0 && idx140 >= 0 && idx135 < idx140 && idx353 < idx140)) {
    errors.push("COMPAT_ORDER_BEFORE_PUBLISHER_CORE_FAILED");
  } else {
    console.log("ORDER_OK platform_account_restrictions and profiles.deactivated_at precede 140000");
  }

  if (errors.length) {
    console.error("MIGRATION_CHAIN_STATIC=FAIL");
    for (const e of errors) console.error(`CODE=${e}`);
    process.exit(1);
  }

  console.log("MIGRATION_CHAIN_STATIC=PASS_STATIC");
  console.log("MIGRATION_CHAIN_CLEAN_RESET=BLOCKED_DOCKER_ENGINE_UNAVAILABLE");
  process.exit(0);
}

main();

/**
 * Generates production release + migration manifests (value-free hashes only).
 * Usage: node scripts/generate-production-release-manifests.mjs [--release-commit=<sha>]
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

function lfSha256(content) {
  const n = String(content).replace(/\r\n/g, "\n").replace(/^\uFEFF/, "");
  return crypto.createHash("sha256").update(n, "utf8").digest("hex");
}

function fileLfSha256(rel) {
  return lfSha256(fs.readFileSync(path.join(root, rel)));
}

function parseArgs(argv) {
  let releaseCommit = null;
  for (const arg of argv) {
    if (arg.startsWith("--release-commit=")) releaseCommit = arg.slice("--release-commit=".length);
  }
  return { releaseCommit };
}

function listEdgeFunctions() {
  const dir = path.join(root, "supabase", "functions");
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && d.name !== "_shared")
    .map((d) => d.name)
    .sort()
    .map((name) => {
      const indexRel = path.join("supabase", "functions", name, "index.ts");
      const full = path.join(root, indexRel);
      return {
        name,
        sourcePath: indexRel.replace(/\\/g, "/"),
        sourceSha256: fs.existsSync(full) ? fileLfSha256(indexRel) : null,
        deployVersion: "NOT_DEPLOYED_THIS_TASK",
        jwtRequired: "UNKNOWN_UNTIL_HOSTED_CANARY",
        rollbackVersion: null,
      };
    });
}

function migrationMeta(filename) {
  const rel = path.join("supabase", "migrations", filename);
  const body = fs.readFileSync(path.join(root, rel), "utf8");
  const timestamp = filename.slice(0, 14);
  const destructive =
    /\bdrop\s+table\b/i.test(body) || /\btruncate\b/i.test(body) || /\bdrop\s+column\b/i.test(body);
  return {
    filename,
    timestamp,
    lfNormalizedSha256: fileLfSha256(rel),
    dependencies: inferDeps(filename),
    tablesFunctionsChanged: summarizeChanged(body),
    estimatedLockRisk: destructive ? "high" : body.length > 80000 ? "medium" : "low",
    destructiveChange: destructive,
    backfillRequired: /backfill|update\s+public\./i.test(body),
    rollbackStrategy: "forward-fix only; do not delete financial/audit rows; disable via feature flags/kill switches",
    validationQuery: inferValidation(filename),
    status: "local_present",
  };
}

function inferDeps(filename) {
  if (filename.startsWith("20260803140000")) {
    return ["20260803135000_platform_account_restrictions_canonical.sql", "20260803135300_profiles_deactivated_at_canonical.sql"];
  }
  if (filename.startsWith("20260803210000")) return ["20260803173000_verification_business_platform_foundation.sql"];
  if (filename.startsWith("20260803220000")) return ["20260803210000_picom_verified_subscription_and_entitlements.sql"];
  if (filename.startsWith("20260803230000")) return ["20260803220000_business_application_verification_and_team_management.sql"];
  if (filename.startsWith("20260803240000")) return ["20260803230000_business_catalog_brand_content_and_promotion_bridge.sql"];
  if (filename.startsWith("20260803250000")) return ["20260803240000_advertiser_campaign_delivery_and_revenue_attribution.sql"];
  if (filename.startsWith("20260803260000")) return ["20260803250000_partner_payout_tax_reconciliation_and_ad_transparency.sql"];
  if (filename.includes("platform_account_restrictions")) return ["profiles"];
  if (filename.includes("profiles_deactivated")) return ["profiles"];
  return [];
}

function summarizeChanged(body) {
  const tables = [...body.matchAll(/create table if not exists public\.([a-z0-9_]+)/gi)].map((m) => m[1]);
  const fns = [...body.matchAll(/create or replace function public\.([a-z0-9_]+)/gi)].map((m) => m[1]);
  return { tables: [...new Set(tables)].slice(0, 40), functions: [...new Set(fns)].slice(0, 40) };
}

function inferValidation(filename) {
  if (filename.includes("platform_account_restrictions")) {
    return "select to_regclass('public.platform_account_restrictions') is not null;";
  }
  if (filename.includes("profiles_deactivated")) {
    return "select exists (select 1 from information_schema.columns where table_name='profiles' and column_name='deactivated_at');";
  }
  if (filename.startsWith("20260803250000")) {
    return "select to_regclass('public.payout_platform_settings') is not null;";
  }
  if (filename.startsWith("20260803260000")) {
    return "select to_regclass('public.feature_canary_allowlist') is not null;";
  }
  return "select 1;";
}

function main() {
  const { releaseCommit: argCommit } = parseArgs(process.argv.slice(2));
  const releaseCommit =
    argCommit ||
    execSync("git rev-parse HEAD", { cwd: root, encoding: "utf8" }).trim();
  const branch = execSync("git branch --show-current", { cwd: root, encoding: "utf8" }).trim();

  const migrationFiles = fs
    .readdirSync(path.join(root, "supabase", "migrations"))
    .filter((f) => f.startsWith("20260803") && f.endsWith(".sql"))
    .sort();

  const migrations = migrationFiles.map(migrationMeta);
  const migrationManifest = {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    releaseCommit,
    branch,
    environmentTarget: "production",
    migrations,
  };
  const migrationJson = `${JSON.stringify(migrationManifest, null, 2)}\n`;
  const migrationManifestSha = lfSha256(migrationJson);

  const rollout = JSON.parse(
    fs.readFileSync(path.join(root, "config", "rollout", "closed-beta.v1.json"), "utf8"),
  );

  const releaseManifest = {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    releaseCommit,
    branch,
    environmentTarget: "production",
    stagingProjectRef: "ufmtvqtsklqsmqxefbbs",
    productionProjectRefCandidate: "cqnsetsmcduraryemhbi",
    productionMutationGuard: "BLOCKED_UNTIL_ENV_COMPLETE",
    migrationFiles,
    migrationSha256List: migrations.map((m) => ({
      filename: m.filename,
      lfNormalizedSha256: m.lfNormalizedSha256,
    })),
    expectedMigrationManifestSha256: migrationManifestSha,
    edgeFunctions: listEdgeFunctions(),
    workerImageDigests: {
      "email-worker": "BLOCKED_NO_IMMUTABLE_DIGEST",
      "event-reminder-worker": "BLOCKED_NO_IMMUTABLE_DIGEST",
      "advertising-scheduler": "BLOCKED_IMAGE_NOT_BUILT",
      "ad-reconciliation-worker": "BLOCKED_IMAGE_NOT_BUILT",
      "invalid-traffic-worker": "BLOCKED_IMAGE_NOT_BUILT",
      "payout-worker": "BLOCKED_IMAGE_NOT_BUILT",
      "payout-reconciliation-worker": "BLOCKED_IMAGE_NOT_BUILT",
      "transparency-archive-worker": "BLOCKED_IMAGE_NOT_BUILT",
      "retention-cleanup-worker": "BLOCKED_IMAGE_NOT_BUILT",
    },
    webBuildArtifactHash: "NOT_COMPUTED_THIS_TASK",
    accountCenterArtifactHash: "NOT_COMPUTED_THIS_TASK",
    desktopArtifactHash: "NOT_COMPUTED_THIS_TASK",
    featureFlagDefaults: rollout.featureFlagDefaults,
    closedBetaConfigVersion: rollout.version,
  };

  const releaseJson = `${JSON.stringify(releaseManifest, null, 2)}\n`;
  const releaseManifestSha = lfSha256(releaseJson);

  fs.mkdirSync(path.join(root, "docs", "release"), { recursive: true });
  fs.writeFileSync(path.join(root, "docs", "release", "production-migration-manifest.json"), migrationJson);
  fs.writeFileSync(
    path.join(root, "docs", "release", "production-migration-manifest.sha256"),
    `${migrationManifestSha}  production-migration-manifest.json\n`,
  );
  fs.writeFileSync(path.join(root, "docs", "release", "production-release-manifest.json"), releaseJson);
  fs.writeFileSync(
    path.join(root, "docs", "release", "production-release-manifest.sha256"),
    `${releaseManifestSha}  production-release-manifest.json\n`,
  );

  console.log(`MIGRATION_MANIFEST_SHA256=${migrationManifestSha}`);
  console.log(`RELEASE_MANIFEST_SHA256=${releaseManifestSha}`);
  console.log(`RELEASE_COMMIT=${releaseCommit}`);
}

main();

/**
 * Hosted / provider canary gate runner — fail-closed.
 * Does not invent provider events. Exits non-zero when external gates are unavailable.
 */
import process from "node:process";

const gates = [
  ["HOSTED_RLS", "BLOCKED", "Real JWT matrix not executed under production mutation guard"],
  ["HOSTED_STORAGE", "BLOCKED", "Hosted storage + malware E2E not executed"],
  ["EDGE_FUNCTION_DEPLOY", "BLOCKED", "Production deploy not authorized"],
  ["STRIPE_BILLING_TEST_MODE_E2E", "BLOCKED", "Stripe test-mode secrets/checkout not evidenced"],
  ["STRIPE_IDENTITY_E2E", "BLOCKED", "Identity provider test-mode not evidenced"],
  ["PAYOUT_PROVIDER_TEST_MODE_E2E", "BLOCKED", "Payout provider test-mode not evidenced"],
  ["REAL_PAYOUT_SEND", "NOT_DONE", "ALLOW_REAL_PAYOUT_CANARY not set"],
  ["TAX_VERIFICATION_E2E", "BLOCKED", "Tax provider not evidenced"],
  ["EMAIL_DELIVERY_E2E", "PARTIAL", "Mailbox receipt not verified; SMTP accepted alone is insufficient"],
  ["HOSTED_WORKER_E2E", "BLOCKED", "Worker images/digests not built; Docker engine down"],
  ["MALWARE_SCANNER_E2E", "BLOCKED", "Scanner E2E not evidenced"],
  ["LEGAL_COPY_ACTIVE", "LEGAL_COPY_REQUIRED", "No real active legal approval evidence"],
];

let blocked = 0;
for (const [name, status, reason] of gates) {
  console.log(`${name}=${status}`);
  console.log(`REASON=${reason}`);
  if (status === "BLOCKED" || status === "LEGAL_COPY_REQUIRED") blocked += 1;
}

console.log(`BLOCKED_GATE_COUNT=${blocked}`);
console.log("REAL_PAYOUT_SEND=NOT_DONE");
process.exit(blocked > 0 ? 2 : 0);

/**
 * Fail-closed production config guard.
 * Blocks production builds/deploys that target known staging Supabase refs
 * or missing/placeholder production infrastructure.
 *
 * Usage:
 *   node scripts/production-config-guard.mjs
 *   node scripts/production-config-guard.mjs --strict-env-file=.env.production
 *
 * Does not print secret values — only variable names and classification codes.
 */
import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const FORBIDDEN_STAGING_REFS = Object.freeze([
  "ufmtvqtsklqsmqxefbbs",
  "kbdotviopwlcqviggtrc",
]);

/** Known dedicated production project — detection only; mutation still requires production-mutation-guard. */
const KNOWN_PRODUCTION_PROJECT_REF = "cqnsetsmcduraryemhbi";

const PLACEHOLDER_PATTERNS = [
  /YOUR_PRODUCTION/i,
  /CHANGE_ME/i,
  /placeholder/i,
  /example\.supabase\.co/i,
];

function parseArgs(argv) {
  let envFile = null;
  let requireProductionMode = true;
  for (const arg of argv) {
    if (arg.startsWith("--strict-env-file=")) envFile = arg.slice("--strict-env-file=".length);
    if (arg === "--allow-non-production-mode") requireProductionMode = false;
  }
  return { envFile, requireProductionMode };
}

function loadEnvFile(filePath) {
  if (!filePath) return {};
  const absolute = path.isAbsolute(filePath) ? filePath : path.join(root, filePath);
  if (!fs.existsSync(absolute)) {
    return { __missing_file: absolute };
  }
  const out = {};
  for (const line of fs.readFileSync(absolute, "utf8").replace(/^\uFEFF/, "").split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#") || !trimmed.includes("=")) continue;
    const i = trimmed.indexOf("=");
    const key = trimmed.slice(0, i).trim();
    let value = trimmed.slice(i + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    out[key] = value;
  }
  return out;
}

function classifyUrl(value) {
  if (!value || !String(value).trim()) return "MISSING";
  const v = String(value).trim();
  if (PLACEHOLDER_PATTERNS.some((re) => re.test(v))) return "PLACEHOLDER";
  for (const ref of FORBIDDEN_STAGING_REFS) {
    if (v.includes(ref)) return `STAGING_REF:${ref}`;
  }
  return "OK";
}

function main() {
  const { envFile, requireProductionMode } = parseArgs(process.argv.slice(2));
  const mode = String(process.env.VITE_APP_ENV || process.env.MODE || process.env.NODE_ENV || "").toLowerCase();
  const fileEnv = loadEnvFile(envFile);
  if (fileEnv.__missing_file) {
    console.error("PICOM_PRODUCTION_CONFIG_GUARD=FAIL");
    console.error("CODE=PRODUCTION_ENV_FILE_MISSING");
    console.error(`FILE=${path.relative(root, fileEnv.__missing_file)}`);
    process.exit(1);
  }

  const merged = { ...fileEnv, ...process.env };
  const errors = [];

  if (requireProductionMode && mode && mode !== "production") {
    // When explicitly invoked as production guard with a production env file, mode must be production.
    if (envFile || String(process.env.PICOM_FORCE_PRODUCTION_GUARD || "") === "1") {
      errors.push("PRODUCTION_CONFIG_INVALID_ENVIRONMENT_NAME");
    }
  }

  if (envFile || String(process.env.PICOM_FORCE_PRODUCTION_GUARD || "") === "1" || mode === "production") {
    const appEnv = String(merged.VITE_APP_ENV || "").trim().toLowerCase();
    if (appEnv && appEnv !== "production") {
      errors.push("PRODUCTION_CONFIG_INVALID_ENVIRONMENT_NAME");
    }

    const urlClass = classifyUrl(merged.VITE_SUPABASE_URL || merged.SUPABASE_URL || "");
    if (urlClass === "MISSING") errors.push("PRODUCTION_CONFIG_MISSING_SUPABASE_URL");
    if (urlClass === "PLACEHOLDER") errors.push("PRODUCTION_CONFIG_PLACEHOLDER_SUPABASE_URL");
    if (urlClass.startsWith("STAGING_REF:")) errors.push("PRODUCTION_CONFIG_INVALID_STAGING_TARGET");

    const ref = String(merged.SUPABASE_PROJECT_REF || merged.VITE_SUPABASE_PROJECT_REF || "").trim();
    if (ref) {
      if (PLACEHOLDER_PATTERNS.some((re) => re.test(ref))) {
        errors.push("PRODUCTION_CONFIG_PLACEHOLDER_PROJECT_REF");
      }
      if (FORBIDDEN_STAGING_REFS.includes(ref)) {
        errors.push("PRODUCTION_CONFIG_INVALID_STAGING_TARGET");
      }
    }

    const declaredProdRef = String(merged.SUPABASE_PRODUCTION_PROJECT_REF || "").trim();
    if (declaredProdRef && FORBIDDEN_STAGING_REFS.includes(declaredProdRef)) {
      errors.push("FATAL_PRODUCTION_AND_STAGING_PROJECT_REFERENCES_MATCH");
    }
    if (
      declaredProdRef &&
      declaredProdRef !== KNOWN_PRODUCTION_PROJECT_REF &&
      String(merged.PICOM_ALLOW_UNLISTED_PRODUCTION_REF || "") !== "1"
    ) {
      errors.push("PRODUCTION_CONFIG_UNKNOWN_PRODUCTION_PROJECT_REF");
    }
    if (ref && declaredProdRef && ref !== declaredProdRef) {
      errors.push("PRODUCTION_CONFIG_PROJECT_REF_MISMATCH");
    }

    const livekitUrl = String(merged.VITE_LIVEKIT_URL || merged.LIVEKIT_URL || "");
    if (livekitUrl && FORBIDDEN_STAGING_REFS.some((r) => livekitUrl.includes(r))) {
      errors.push("PRODUCTION_CONFIG_INVALID_STAGING_TARGET");
    }
    if (String(merged.PICOM_LIVEKIT_ENV || "").toLowerCase() === "staging" && mode === "production") {
      errors.push("PRODUCTION_CONFIG_LIVEKIT_MARKED_STAGING");
    }
    if (String(merged.PICOM_WORKER_ENV || "").toLowerCase() === "staging" && mode === "production") {
      errors.push("PRODUCTION_CONFIG_WORKER_MARKED_STAGING");
    }
  } else {
    console.log("PICOM_PRODUCTION_CONFIG_GUARD=SKIP");
    console.log("REASON=non_production_mode");
    process.exit(0);
  }

  if (errors.length) {
    console.error("PICOM_PRODUCTION_CONFIG_GUARD=FAIL");
    for (const code of [...new Set(errors)]) {
      console.error(`CODE=${code}`);
    }
    process.exit(1);
  }

  console.log("PICOM_PRODUCTION_CONFIG_GUARD=PASS");
  process.exit(0);
}

main();
